<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\User;use App\Modules\Counselor\Models\{Counselor,Specialty,Comment};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class ManagementController extends Controller {
 public function dashboard(){
  $day=\Illuminate\Support\Carbon::now('Asia/Tehran')->startOfDay();
  $from=$day->copy()->utc()->toDateTimeString();$to=$day->copy()->addDay()->utc()->toDateTimeString();
  return ['counselors'=>Counselor::count(),'specialties'=>Specialty::count(),'comments'=>Comment::count(),
   'pending_comments'=>Comment::where('is_approved',false)->count(),'users'=>User::count(),
   'appointments'=>DB::table('appointment_requests')->count(),
   'booking_today'=>DB::table('bookings')->where('starts_at','>=',$from)->where('starts_at','<',$to)->whereIn('status',['confirmed','completed'])->count(),
   'booking_pending'=>DB::table('bookings')->where('status','held')->where('hold_expires_at','>',now()->utc()->toDateTimeString())->count(),
   'booking_collected_irr'=>(int)DB::table('booking_payments')->where('status','verified')->sum('amount_irr')];
 }
 public function counselors(){return Counselor::with('specialties')->latest()->paginate(20);}
 public function specialties(){return Specialty::latest()->paginate(20);}
 public function comments(){return Comment::latest()->paginate(20);}
 public function users(Request $r){abort_unless($r->user()->is_admin,403);$v=$r->validate(['q'=>'nullable|string|max:120','role_id'=>'nullable|integer|exists:admin_roles,id','is_active'=>'nullable|boolean','per_page'=>'nullable|integer|min:1|max:100']);$query=User::select('id','name','email','phone','is_admin','is_active','created_at')->with('roles:id,name,label')->when($v['q']??null,fn($q,$term)=>$q->where(fn($w)=>$w->where('name','like','%'.$term.'%')->orWhere('email','like','%'.$term.'%')->orWhere('phone','like','%'.$term.'%')))->when(isset($v['is_active']),fn($q)=>$q->where('is_active',$v['is_active']))->when($v['role_id']??null,fn($q,$id)=>$q->whereHas('roles',fn($role)=>$role->where('admin_roles.id',$id)));return $query->latest()->paginate($v['per_page']??20);}
 public function userStore(Request $r){abort_unless($r->user()->is_admin,403);$v=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','is_admin'=>'sometimes|boolean','admin_permissions'=>'sometimes|array','admin_permissions.*'=>'string|in:dashboard.view,users.manage,counselors.manage,specialties.manage,comments.manage,content.manage,appointments.manage,settings.manage,finance.view,finance.manage,notes.manage','is_active'=>'sometimes|boolean']);$v['is_admin']=$v['is_admin']??false;$user=User::create($v);DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'admin.user_created','details'=>json_encode(['user_id'=>$user->id,'is_admin'=>$user->is_admin]),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['data'=>$user->only('id','name','email','is_admin','is_active')],201);}
 public function userUpdate(Request $r,User $user){abort_unless($r->user()->is_admin,403);$v=$r->validate(['name'=>'sometimes|required|string|max:255','email'=>['sometimes','required','email',Rule::unique('users','email')->ignore($user->id)],'password'=>'sometimes|string|min:12','is_admin'=>'sometimes|boolean','is_active'=>'sometimes|boolean','admin_permissions'=>'sometimes|array','admin_permissions.*'=>'string|in:dashboard.view,users.manage,counselors.manage,specialties.manage,comments.manage,content.manage,appointments.manage,settings.manage,finance.view,finance.manage,notes.manage']);$removesAdmin=($user->is_admin && (($v['is_admin']??true)===false || ($v['is_active']??true)===false));if($removesAdmin)abort_if(User::where('is_admin',true)->where('is_active',true)->count()<=1,409,'Cannot remove the last active super-admin.');if($user->id===$r->user()->id && (($v['is_admin']??true)===false || ($v['is_active']??true)===false))abort(422,'Cannot revoke own active admin access');$user->update($v);if(($v['is_active']??true)===false || array_key_exists('is_admin',$v) || array_key_exists('admin_permissions',$v))DB::table('personal_access_tokens')->where('tokenable_type',User::class)->where('tokenable_id',$user->id)->delete();DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'admin.user_updated','details'=>json_encode(['user_id'=>$user->id,'fields'=>array_keys($v)]),'created_at'=>now(),'updated_at'=>now()]);return ['data'=>$user->only('id','name','email','is_admin','is_active')];}
 public function userDestroy(Request $r,User $user){abort_unless($r->user()->is_admin,403);abort_if($r->user()->id===$user->id,422,'Cannot delete own account');abort_if($user->is_admin && $user->is_active && User::where('is_admin',true)->where('is_active',true)->count()<=1,409,'Cannot delete the last active super-admin');$user->tokens()->delete();$user->delete();DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'admin.user_deleted','details'=>json_encode(['user_id'=>$user->id]),'created_at'=>now(),'updated_at'=>now()]);return response()->noContent();}
 public function settings(){$values=DB::table('cms_settings')->pluck('value','key');foreach($values as $key=>$value)if(preg_match('/secret|password|token|credential|api[_-]?key|merchant/i',$key))$values[$key]='[REDACTED]';return $values;}
 public function settingUpdate(Request $r){$v=$r->validate(['key'=>'required|string|max:255|not_regex:/secret|password|token|credential|api[_-]?key|merchant/i','value'=>'nullable|string|max:20000']);DB::table('cms_settings')->updateOrInsert(['key'=>$v['key']],['value'=>$v['value']??null,'updated_at'=>now(),'created_at'=>now()]);DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'settings.generic_updated','details'=>json_encode(['key'=>$v['key']]),'created_at'=>now(),'updated_at'=>now()]);return ['ok'=>true];}
 public function appointments(){return DB::table('appointment_requests')->orderByDesc('id')->paginate(20);}
 public function appointmentStore(Request $r){$v=$r->validate(['counselor_id'=>'nullable|exists:counselors,id','name'=>'required|string|max:255','phone'=>'required|string|max:30','preferred_at'=>'nullable|date','notes'=>'nullable|string|max:5000']);$id=DB::table('appointment_requests')->insertGetId([...$v,'status'=>'new','created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id],201);}
 public function appointmentUpdate(Request $r,int $id){$v=$r->validate(['status'=>['required',Rule::in(['new','contacted','confirmed','cancelled','completed'])]]);abort_unless(DB::table('appointment_requests')->where('id',$id)->update([...$v,'updated_at'=>now()]),404);return ['ok'=>true];}
}
